"""Build an isolated public entry from immutable Y10/Y4 owner inputs. No shared edits."""
from pathlib import Path
import json,hashlib,html,os,subprocess
Y=Path(__file__).resolve().parent;R=Y.parents[1];REPO=R.parent
BASE='a9134318402f87f9e1d61864f76f834c0e8df174'
ASSET='b2966e8265edbd6d52ac2fa7aa1aaa764683df5ff1548a21c8cc1a024fdb3d48'
assert hashlib.sha256((R/'live/assets/ATLAS_D_Original.glb').read_bytes()).hexdigest()==ASSET
if (REPO/'.git').exists():
 subprocess.run(['git','fetch','--depth=1','origin',BASE],cwd=REPO,check=True)
 changes=subprocess.check_output(['git','diff','--name-only',BASE,'HEAD'],cwd=REPO,text=True).splitlines()
 assert all(p.startswith('atlas_d_simulator_01/contact/y11/') or p=='.github/workflows/atlas-d-simulator-01.yml' for p in changes),changes
(Y/'host').mkdir(exist_ok=True)
s=(R/'live/index.html').read_text().replace('<head>','<head><base href="../../../live/">',1).replace('<script defer src="atlas-d-core.js"></script>','<script defer src="atlas-d-core.js"></script><script defer src="../contact/y11/physics.js"></script>',1)
assert s.count('../contact/y11/physics.js')==1
(Y/'host/index.html').write_text(s)
s=(R/'contact/y10/preview.html').read_text().replace('ATLAS D Y10 · isolated boarding label','ATLAS D · live yacht and submarine concept').replace('Y10 · ISOLATED','Y11 · SOLO DEMO').replace('src="../../live/index.html?vessel=bay"','src="../y11/host/index.html?vessel=bay"').replace('Y10 boarding label preview','ATLAS D · measured physics demo').replace('Physics, original asset, Y1–Y3 contracts and owner time are unchanged.','New Y11 force-based maneuvering and damped wave response. Original yacht, input controls, contact geometry and host clock are retained. Mass and hydrodynamic coefficients are authored concept assumptions—not measured sea trials.').replace('src="../y4/preview.js"','src="../y11/preview.js"').replace('</body>','<script src="../y11/telemetry.js"></script></body>')
s=s.replace('<div id="status"','<p><a href="../y11/report.html" target="_blank" rel="noopener">Open physics measurements and assumptions ↗</a></p><div id="status"')
(Y/'preview.html').write_text(s)
s=(R/'contact/y4/preview.js').read_text().replace("view:'station'","view:'overview'").replace('y4-fixture-r7-instance','y11-force-r7-instance').replace('y4-isolated-owner-host','y11-isolated-owner-host').replace('y4-r7-authored-proving-ground-fixture','y11-r7-authored-proving-force-model-v1').replace('out.ready=true;',"cameraChoice('overview');out.ready=true;")
(Y/'preview.js').write_text(s)
m=json.loads((Y/'physics-results.json').read_text());assert m['passed']
keys=[('steadyKnots','Steady straight speed','kn'),('timeTo10KnotsS','Time from rest to 10 kn','s'),('timeTo90PercentS','Time to 90% steady speed','s'),('peakLongitudinalAccelerationMps2','Peak forward acceleration','m/s²'),('coastToHalfMpsS','Neutral coast to 0.5 m/s','s'),('coastDistanceM','Distance in that coast','m'),('crashStopS','Full reverse: first zero forward speed','s'),('crashStopDistanceM','Full reverse: stopping distance','m'),('turnAdvanceM','Full-rudder advance to 90°','m'),('tacticalDiameterM','Full-rudder tactical diameter at 180°','m')]
rows=''.join(f'<tr><td>{label}</td><td>{m["baseline"][k]:.3f}</td><td>{m["candidate"][k]:.3f} {unit}</td></tr>' for k,label,unit in keys)
tests=''.join('<li>'+html.escape(t['name'])+'</li>' for t in m['tests'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ATLAS D — published physics measurements</title><style>body{font:16px/1.6 system-ui;background:#0c2431;color:#e5edf1;max-width:980px;margin:auto;padding:30px 20px}h1{font-size:36px;line-height:1.15}h2{margin-top:35px}a{color:#e2c18b}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{text-align:left;border-bottom:1px solid #48616d;padding:10px}pre{overflow:auto;background:#153947;padding:18px;font-size:12px}.tag{color:#e2c18b;letter-spacing:2px}.note{border-left:3px solid #d2b582;padding:10px 18px;background:#143440}li{margin:5px 0}@media(max-width:600px){body{font-size:14px;padding:18px 10px}td,th{padding:7px}h1{font-size:29px}}</style><p class="tag">ATLAS D · Y11 · SINGLE-PLAYER CONCEPT DEMO</p><h1>Physics you can inspect.<br>Measurements you can reproduce.</h1><p><a href="preview.html">Launch latest yacht demo →</a> · <a href="physics-results.json">Raw measurements and turn traces</a> · <a href="build.json">File fingerprints</a></p><div class="note"><strong>Measured in simulation—not sea-trial validated.</strong> The original 82.9 m yacht geometry is preserved. Mass, added mass, damping, thrust, rudder coefficients and restoring periods are authored assumptions. These are not certified real-vessel specifications, and no pressure-hull rating is claimed.</div><h2>What changed</h2><p>Direct target-speed interpolation was replaced with a 3-degree-of-freedom force model: surge, sway and yaw inertia, energy-consistent Coriolis coupling, linear/quadratic damping, distributed hull crossflow, rudder side force and bow-thruster moment. Thrust and rudder actuators respond gradually. Heave, roll and pitch use separate damped restoring equations instead of immediately copying wave slopes.</p><p>The same owner 60 Hz simulation step drives the model; there is no second vessel clock. Original input handlers, conversion sequence and the >4-second stall pause remain. Unknown bottom data remains unknown. The original 39-point footprint gains an additional conservative tilt allowance. Depth control is still the bounded inherited concept controller, not a validated ballast or submarine dynamics model.</p><h2>Identical scripted maneuvers</h2><p>Draft datum 4.507 m; flat 200 m-deep synthetic test water; calm waves; 1/60-second step. Acceleration begins at rest with full forward command. Coast, stopping and turning start after 720 seconds of full-forward equilibration. Full reverse means immediate command reversal with physical speed continuity. These are not regulatory trials or pass/fail maneuvering standards.</p><table><thead><tr><th>Measurement</th><th>Earlier controller</th><th>Y11 force model</th></tr></thead><tbody>ROWS</tbody></table><h2>Numerical and safety checks</h2><p>COUNT focused checks pass. They test mathematical consistency and stated safeguards, not whether the authored parameters match a real yacht.</p><ul>TESTS</ul><h2>Parameters</h2><pre>PARAMS</pre><h2>Reproduce</h2><pre>node atlas_d_simulator_01/contact/y11/test-physics.cjs</pre><p>The script emits physics-results.json. Source and parameter fingerprints are recorded in build.json. A passing deterministic run does not itself certify public-browser loading; the live browser report is retained in the release workflow artifacts and PR1 handoff.</p><h2>Model basis and limits</h2><p><a href="https://www.fossen.biz/html/marineCraftModel.html">Fossen: marine craft equations, mass, Coriolis and damping</a>; <a href="https://onlinelibrary.wiley.com/doi/10.1002/9781119575016.ch4">Fossen: hydrostatic restoring motion</a>. Our simplified rudder model is not MARIN's calibrated four-quadrant model. No tank-test/CFD/sea-trial coefficients, wind/current forcing, structural damage, flooding, swept collision proof, human occupancy approval or multiplayer are included.</p><p>This is isolated from CORE's integrated simulator. Phone-sized Chromium verification is not physical-phone/Safari or performance certification.</p></html>'''
page=page.replace('ROWS',rows).replace('COUNT',str(m['total'])).replace('TESTS',tests).replace('PARAMS',html.escape(json.dumps(m['parameters'],indent=2)))
(Y/'report.html').write_text(page)
files=[p for p in Y.rglob('*') if p.is_file() and p.suffix in ['.js','.json','.html','.cjs','.py'] and p.name!='build.json' and 'evidence' not in p.parts]
manifest={'release':'Y11 isolated force-model demo','sourceCommit':os.environ.get('GITHUB_SHA','local-unpublished'),'baselineCommit':BASE,'model':m['model'],'assetSHA256':ASSET,'parameterSource':'authored concept, not measured sea-trial data','multiplayer':False,'sharedHostMerged':False,'tests':m['total'],'files':{str(p.relative_to(Y)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files},'inherited':{str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [R/'live/atlas-d.js',R/'live/atlas-d-core.js',R/'contact/y4/preview.js',R/'contact/y9/pause-recovery.js',R/'contact/y10/boarding-label.js']}}
(Y/'build.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps({'built':True,'source':manifest['sourceCommit'],'tests':m['total']}))
